/*
 * Copy-on-write support.
 *
 * When an export is exported with the copyonwrite option, writes do not go
 * to the master file. Instead, they are stored in a per-connection diff
 * file, which is removed again when the connection is closed, so that the
 * master file is left untouched. Reads check the diff file first and fall
 * back to the master file for pages that have not been written.
 *
 * The diff file comes in two layouts. If the sparse_cow option is in
 * effect, the diff file is a sparse file of the same size as the export,
 * and every modified page is stored at the offset it has in the export.
 * Without sparse_cow, every modified page is appended to the end of the
 * diff file in the order in which pages are first modified; the position
 * of a page in the diff file is determined by the number of pages before
 * it that are also present in the diff file.
 *
 * In both layouts, a bitmap tracks which pages of the export are present
 * in the diff file. Pages are always stored in the diff file in their
 * entirety; when a write covers only part of a page that is not in the
 * diff file yet, the rest of the page is read from the master file so
 * that the page in the diff file is complete.
 */

/** number of bytes needed for the diff bitmap of an export of size bytes */
#define DIFFMAPSIZE(bytes) ((((bytes) + DIFFPAGESIZE - 1) / DIFFPAGESIZE + 7) / 8)

/**
 * Test whether a page is present in the diff file
 *
 * @param map the diff file bitmap
 * @param page the page to check
 * @return true if the page is present in the diff file
 **/
static inline bool diffmap_test(const uint8_t *map, uint64_t page) {
	return (map[page / 8] >> (page % 8)) & 1;
}

/**
 * Mark a page as present in the diff file
 *
 * @param map the diff file bitmap
 * @param page the page to mark
 **/
static inline void diffmap_set(uint8_t *map, uint64_t page) {
	map[page / 8] |= 1 << (page % 8);
}

/**
 * Count the number of pages present in the diff file before a given page.
 * For non-sparse diff files, this is the index at which the given page is
 * stored in the diff file.
 *
 * @param map the diff file bitmap
 * @param page the page before which to count
 * @return the number of pages present in the diff file before page
 **/
static uint64_t diffmap_count(const uint8_t *map, uint64_t page) {
	uint64_t count = 0;
	uint64_t i;

	for (i = 0; i < page / 8; i++) {
		count += __builtin_popcount(map[i]);
	}
	if (page % 8) {
		count += __builtin_popcount(map[page / 8] & ((1 << (page % 8)) - 1));
	}
	return count;
}

/**
 * Get the offset at which a page is stored in the diff file
 *
 * @param client The client we're serving for
 * @param page The page to get the offset for
 * @return the offset of the page in the diff file
 **/
static off_t difffile_offset(CLIENT *client, uint64_t page) {
	if (client->server->flags & F_SPARSE) {
		return (off_t)page * DIFFPAGESIZE;
	}
	return (off_t)diffmap_count(client->difmap, page) * DIFFPAGESIZE;
}
