/*
 * Copy-on-write support.
 *
 * When an export is exported with the copy-on-write option, writes are not
 * done to the master file, but to a per-connection diff file, which is
 * removed again when the connection is closed; as a result, the master file
 * is never modified, and all writes are lost upon disconnecting. Reads
 * check the diff file first, and fall back to the master file only for
 * pages that have not been written to.
 *
 * Two layouts for the diff file are supported. If the sparse_cow option is
 * in effect, the diff file is a sparse file as large as the export, and
 * every modified page is stored at the offset it has in the export. If it
 * is not, every modified page is appended to the end of the diff file in
 * the order in which pages are first modified; the position of a page in
 * the diff file is the number of pages before it which are present in the
 * diff file as well.
 *
 * In both layouts, a bitmap tracks which pages of the export are present
 * in the diff file. Pages are stored in the diff file in their entirety;
 * when a write covers only part of a page which is not in the diff file
 * yet, the remainder of the page is read from the master file so that the
 * page stored in the diff file is complete.
 */

/** number of bytes needed for the diff bitmap of an export of the given
 * size */
#define DIFFMAPSIZE(bytes) ((((bytes) + DIFFPAGESIZE - 1) / DIFFPAGESIZE + 7) / 8)

/**
 * Read an amount of bytes at a given offset from the right file, bypassing
 * the copy-on-write layer. This abstracts the read-side of the multiple
 * file option.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t masterread(off_t a, char *buf, size_t len, CLIENT *client) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	DEBUG("(READ from fd %d offset %llu len %u), ", fhandle, (long long unsigned int)foffset, (unsigned int)len);

	retval = pread(fhandle, buf, len, foffset);
        if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}

/**
 * Write an amount of bytes at a given offset to the right file, bypassing
 * the copy-on-write layer. This abstracts the write-side of the multiple
 * file option.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
static ssize_t masterwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	DEBUG("(WRITE to fd %d offset %llu len %u fua %d), ", fhandle, (long long unsigned)foffset, (unsigned int)len, fua);

	retval = pwrite(fhandle, buf, len, foffset);
	if(client->server->flags & F_SYNC) {
		fsync(fhandle);
	} else if (fua) {
		fdatasync(fhandle);
	}
	/* close file pointer in case of treefiles */
        if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}

/**
 * Test whether a page is present in the diff file
 *
 * @param map the diff file bitmap
 * @param page the page to test
 * @return true if the page is present in the diff file, false otherwise
 **/
static inline bool diffmap_test(const uint8_t *map, uint64_t page) {
	return (map[page / 8] >> (page % 8)) & 1;
}

/**
 * Mark a page as present in the diff file
 *
 * @param map the diff file bitmap
 * @param page the page to mark
 **/
static inline void diffmap_set(uint8_t *map, uint64_t page) {
	map[page / 8] |= 1 << (page % 8);
}

/**
 * Count the pages present in the diff file before the given page. For a
 * non-sparse diff file, this is the index at which the given page is
 * stored in the diff file.
 *
 * @param map the diff file bitmap
 * @param page the page before which to count
 * @return the number of pages present in the diff file before page
 **/
static uint64_t diffmap_count(const uint8_t *map, uint64_t page) {
	uint64_t count = 0;
	uint64_t i;

	for (i = 0; i < page / 8; i++) {
		count += __builtin_popcount(map[i]);
	}
	if (page % 8) {
		count += __builtin_popcount(map[page / 8] & ((1 << (page % 8)) - 1));
	}
	return count;
}

/**
 * Get the offset at which a page is stored in the diff file
 *
 * @param client The client we're serving for
 * @param page The page to get the offset for
 * @return the offset of the page in the diff file
 **/
static off_t difffile_offset(CLIENT *client, uint64_t page) {
	if (client->server->flags & F_SPARSE) {
		return (off_t)page * DIFFPAGESIZE;
	}
	return (off_t)(diffmap_count(client->difmap, page) * DIFFPAGESIZE);
}

/**
 * Write an entire buffer at a given offset of a file descriptor,
 * restarting interrupted writes and continuing after partial ones
 *
 * @param fd The file descriptor to write to
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param off The offset to write at
 * @return len on success, -1 on failure
 **/
static ssize_t pwrite_fully_fd(int fd, const char *buf, size_t len, off_t off) {
	size_t done = 0;

	while (done < len) {
		ssize_t w = pwrite(fd, buf + done, len - done, off + done);
		if (w < 0) {
			if (errno == EINTR) {
				continue;
			}
			return -1;
		}
		done += w;
	}
	return done;
