 *
 * @param client The client whose diff file should be cleaned up
 **/
static void difffile_cleanup(CLIENT *client) {
	if (!client->difffilename) {
		return;
	}
	DEBUG("Removing copy-on-write diff file %s\n", client->difffilename);
	if (client->difffile != -1) {
		close(client->difffile);
		client->difffile = -1;
	}
	unlink(client->difffilename);
	g_free(client->difffilename);
	client->difffilename = NULL;
	if (client->difmap) {
		g_free(client->difmap);
		client->difmap = NULL;
