static ssize_t difffile_read(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t done = 0;
	ssize_t r = 0;

	pthread_rwlock_rdlock(&client->export_lock);
	while (done < len && r >= 0) {
		off_t cur = a + done;
		uint64_t page = cur / DIFFPAGESIZE;
		size_t pageoff = cur % DIFFPAGESIZE;
		size_t chunk = MIN(len - done, (size_t)DIFFPAGESIZE - pageoff);

